const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry Definition: Tshopo province, Democratic Republic of Congo
    const gadm = ee.FeatureCollection('FAO/GAUL/2015/level1');
    const tshopo = gadm.filter(
      ee.Filter.and(
        ee.Filter.eq('ADM0_NAME', 'Democratic Republic of the Congo'),
        ee.Filter.eq('ADM1_NAME', 'Tshopo')
      )
    );

    if (tshopo.size().getInfo() === 0) {
      console.log("C1: Tshopo province geometry not found.");
      return;
    }

    const geometry = tshopo.geometry();

    // 2. Data Acquisition: Hansen Global Forest Change v1.10
    const gfc = ee.Image('UMD/hansen/global_forest_change_v1_10');

    // Select the 'loss' band, which indicates the year of tree cover loss (1 for 2001, ..., 22 for 2022).
    // A value of 0 means no loss.
    const lossImage = gfc.select('loss');

    // Filter for loss since 2001 (loss year > 0 means loss occurred between 2001 and 2022)
    // The question implies loss from 2001 onwards.
    const treeLossSince2001 = lossImage.gt(0); // This creates a binary mask (1 where loss, 0 where no loss)

    // Calculate the area of each pixel in square meters.
    const pixelArea = ee.Image.pixelArea();

    // Multiply the loss mask by the pixel area to get the area of lost pixels in square meters.
    const lostAreaSqM = treeLossSince2001.multiply(pixelArea);

    // 3. Calculation: Sum the lost area over the Tshopo province.
    // Use a large scale to speed up calculation for large areas.
    const stats = lostAreaSqM.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geometry,
      scale: 1000, // meters, suitable for provincial scale
      maxPixels: 1e9,
    });

    const totalLossSqM = stats.get('loss').getInfo();

    if (totalLossSqM === null || totalLossSqM === undefined) {
      // Check if reduceRegion returned null, possibly due to no valid pixels or an error.
      // We will re-check valid pixels explicitly.
      const validPixelsCheck = treeLossSince2001.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geometry,
        scale: 1000,
        maxPixels: 1e9,
      }).get('loss').getInfo();

      if (validPixelsCheck === 0) {
        console.log("C2: No valid pixels found within the geometry for tree cover loss calculation.");
        return;
      } else {
        console.log("C3: Calculation of total loss returned an invalid result (null/undefined).");
        return;
      }
    }

    // Convert total loss from square meters to square kilometers
    const totalLossSqKm = totalLossSqM / 1e6; // 1e6 sq m = 1 sq km

    const thresholdSqKm = 15000; // The threshold in square kilometers

    console.log(`Calculated Tree Cover Loss (since 2001) in Tshopo: ${totalLossSqKm.toFixed(2)} sq km`);
    console.log(`Threshold for comparison: ${thresholdSqKm} sq km`);

    // 5. Validation & Final Answer
    if (totalLossSqKm < thresholdSqKm) {
      console.log("A"); // Less than 15,000 sq km
    } else {
      console.log("B"); // Not less than 15,000 sq km
    }

  } catch (error) {
    console.log(`D: An error occurred: ${error.message}`);
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
